        clGetDeviceIDs(platforms[plat_id], type, 0, NULL, &num_devices), err,
        plat);
    MEM_CHECK(devices =
                  (cl_device_id *)malloc(sizeof(cl_device_id) * num_devices),
              err, plat);
    OCLERROR_RET(
        clGetDeviceIDs(platforms[plat_id], type, num_devices, devices, NULL),
        err, dev);

