196:     // read number of devices
197:     OCLERROR_RET(clGetProgramInfo(program, CL_PROGRAM_NUM_DEVICES,
198:                                   sizeof(cl_uint), &num_devices, NULL),
199:                  error, end);
200:     if (num_devices == 0) return CL_INVALID_PROGRAM_EXECUTABLE;
201: 
202:     // read the binaries size
203:     binaries_size_alloc_size = sizeof(size_t) * num_devices;
204:     MEM_CHECK(binaries_size = (size_t *)malloc(binaries_size_alloc_size), error,
205:               end);
206: 
207:     OCLERROR_RET(clGetProgramInfo(program, CL_PROGRAM_BINARY_SIZES,
208:                                   binaries_size_alloc_size, binaries_size,
209:                                   NULL),
210:                  error, end);
211: 
212:     // read the binaries
213:     binaries_ptr_alloc_size = sizeof(unsigned char *) * num_devices;
214:     MEM_CHECK(binaries_ptr = (unsigned char **)malloc(binaries_ptr_alloc_size),
215:               error, end);
216:     memset(binaries_ptr, 0, binaries_ptr_alloc_size);
217: 
218:     for (cl_uint i = 0; i < num_devices; ++i)
219:         MEM_CHECK(binaries_ptr[i] = (unsigned char *)malloc(binaries_size[i]),
220:                   error, end);
221: 
222:     OCLERROR_RET(clGetProgramInfo(program, CL_PROGRAM_BINARIES,
223:                                   binaries_ptr_alloc_size, binaries_ptr, NULL),
224:                  error, end);
