330:                  err, end);
331: 
332: end: // cleanup
333:     if (binaries_ptr != NULL)
334:     {
335:         for (cl_uint i = 0; i < num_devices; ++i) free(binaries_ptr[i]);
336:         free(binaries_ptr);
