            error = CL_INVALID_VALUE;
    }

end: // cleanup
    if (binaries_ptr != NULL)
    {
        for (cl_uint i = 0; i < num_devices; ++i) free(binaries_ptr[i]);
        free(binaries_ptr);
    }
    free(binaries_size);

    return error;
}

// function to read binaries of OpenCL compiled program
// read binaries from files of file names "(program_file_name)_(name of
// device).bin"
UTILS_EXPORT
cl_program cl_util_read_binaries(const cl_context context,
                                 const cl_device_id *const devices,
                                 const cl_uint num_devices,
                                 const char *const program_file_name,
                                 cl_int *const error)
{
    cl_int err = CL_SUCCESS;
    size_t binaries_size_alloc_size = 0;
    size_t binaries_ptr_alloc_size = 0;
    size_t *binaries_size = NULL;
    unsigned char **binaries_ptr = NULL;
    cl_program program = NULL;

    // array for binaries' sizes
    binaries_size_alloc_size = sizeof(size_t) * num_devices;
    MEM_CHECK(binaries_size = (size_t *)malloc(binaries_size_alloc_size), err,
              end);

    // array for the binaries
    binaries_ptr_alloc_size = sizeof(unsigned char *) * num_devices;
    MEM_CHECK(binaries_ptr = (unsigned char **)malloc(binaries_ptr_alloc_size),
              err, end);
    memset(binaries_ptr, 0, binaries_ptr_alloc_size);

    // read binaries from files
    for (cl_uint i = 0; i < num_devices; ++i)
    {
        // get device name
        char name_data[201];
        OCLERROR_RET(clGetDeviceInfo(devices[i], CL_DEVICE_NAME,
                                     sizeof(name_data) - 1, name_data, NULL),
                     err, end);
        name_data[200] = '\0';
        // create input file name
        char filename[256];
        snprintf(filename, sizeof(filename), "%s-%s.bin", program_file_name,
                 name_data);

        binaries_ptr[i] =
            cl_util_read_binary_file(filename, binaries_size + i, &err);
        if (err == CL_INVALID_VALUE)
        {
            fprintf(stderr, "No suitable file %s found\n", filename);
            goto end;
        }
        else if (err != CL_SUCCESS)
            goto end;
    }

    OCLERROR_PAR(program = clCreateProgramWithBinary(
                     context, num_devices, devices, binaries_size,
                     (const unsigned char **)binaries_ptr, &err, NULL),
                 err, end);

end: // cleanup
    if (binaries_ptr != NULL)
    {
        for (cl_uint i = 0; i < num_devices; ++i) free(binaries_ptr[i]);
        free(binaries_ptr);
    }
    free(binaries_size);

    if (error != NULL) *error = err;
    return program;
}

UTILS_EXPORT
cl_int cl_util_executable_folder(char *const filename, size_t *const length)
{
    cl_int err = CL_SUCCESS;
    int wai_length, wai_dirname_length = 0;
    char *wai_filename = NULL;

#define IF_ERR(func, error_type, label)                                        \
    do                                                                         \
    {                                                                          \
        if (func)                                                              \
        {                                                                      \
            err = error_type;                                                  \
            goto label;                                                        \
        }                                                                      \
    } while (0)

    wai_length = wai_getExecutablePath(NULL, 0, NULL);
    IF_ERR(wai_length == -1, CL_UTIL_FILE_OPERATION_ERROR, end);
    MEM_CHECK(wai_filename = (char *)malloc(wai_length), err, end);
    IF_ERR(wai_getExecutablePath(wai_filename, wai_length, &wai_dirname_length)
               == -1,
           CL_UTIL_FILE_OPERATION_ERROR, end);

    if (length != NULL)
    {
        *length = (int)wai_dirname_length + 1;
    }

    if (filename != NULL)
    {
        memmove(filename, wai_filename, wai_dirname_length);
        filename[wai_dirname_length] = '\0';
    }

end:
    free(wai_filename);

    return err;
}

// read all the text file contents securely in ANSI C89
// return pointer to C-string with file contents
// interprets filename relative to the folder containing
// the running executable
UTILS_EXPORT
char *cl_util_read_exe_relative_text_file(const char *const rel_path,
                                          size_t *const length,
                                          cl_int *const error)
{
    char *result = NULL;
    size_t result_size = 0;
    char *abs_path = NULL;
    cl_int err = CL_SUCCESS;
    size_t exe_folder_length;
    OCLERROR_RET(cl_util_executable_folder(NULL, &exe_folder_length), err, end);
    MEM_CHECK(abs_path =
                  (char *)malloc(exe_folder_length + strlen(rel_path) + 1),
              err, end);
    OCLERROR_RET(cl_util_executable_folder(abs_path, NULL), err, end);
    strcat(strcat(abs_path, "/"), rel_path);
    OCLERROR_PAR(result = cl_util_read_text_file(abs_path, &result_size, &err),
                 err, end);

    if (length != NULL) *length = result_size;

    if (error != NULL) *error = err;
end:
    free(abs_path);

    return result;
